  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"712_coaching_ankle_pogo_source_48_candidate_materialization","researchVersion":"2026-07-25.7","definition":{"facilityId":1,"legacyExerciseId":48,"preserveLegacyExerciseId":true,"slug":"ankle-pogo-in-place","canonicalName":"Stationary Bilateral Ankle Pogo","displayName":"Stationary Bilateral Ankle Pogo","aliases":["Low Pogos","Low Pogo Jumps","Ankle Pogo","Pogo Jumps in Place","Fast Low Pogos"],"description":"From a tall stationary bilateral stance on a clear, level, non-slip surface, make repeated low-amplitude vertical hops with simultaneous two-foot takeoff and landing. Contacts remain quiet, centred, and spring-like; the ankles and feet provide the visible primary motion while the knees and hips remain softly available rather than locked. One hop is one takeoff and one bilateral landing. This excludes travel, unilateral or alternating contacts, a rope, obstacle clearance, high-amplitude jumping, a squat-jump strategy, a sprint drill, and an assessment.","familyKey":"stationary_bilateral_ankle_pogo","schemaVersion":"2.0.0","cardVersion":4,"status":"review","identityContract":"stationary_simultaneous_bilateral_low_amplitude_vertical_hops_with_quiet_ankle_dominant_contacts","confidence":{"content":80,"scoring":48,"media":50},"movementPatterns":["bilateral_bounce_contact","vertical_rebound","short_ground_contact"],"bodyRegions":["foot","ankle","calf","knee","hip","core"],"requiredEquipment":["none"],"optionalEquipment":["timer","video"],"environment":{"surface":"clear, level, dry, non-slip, impact-appropriate surface","space":"one protected stationary landing station with adequate overhead clearance and no cross traffic","stationCapacity":1,"inspection":["surface traction, debris, moisture, and clearance","footwear or facility foot-covering policy","visible landing area, entry, exit, and coach sightline"],"changeRule":"Changing amplitude, contact pattern, displacement, cadence, surfa